Lemma rblock_inside st LB m blk :
  MFACTS_g (resv:=ref_reserved) st LB -> rmrep st m -> In blk LB ->
  exists r g idx, (s_regions st) !! (fst (blk_slot blk)) = Some r /\ r_kind r = RKGroup
