    /\ r_base r <= blk_addr blk /\ blk_addr blk + blk_size blk <= r_base r + round_up_pg (r_len r)
    /\ 0 <= blk_size blk
    /\ 4096 <= r_base r /\ r_base r + round_up_pg (r_len r) <= ATOP
    /\ (r_base r + round_up_pg (r_len r) <= 0x10000 \/ 0x59000 <= r_base r).
Proof.
