Lemma RHEAP_init_proof : forall (m : mem) (auxv : word),
  (forall a : word, 0x57b30 <= bv_unsigned a < 0x57ed8 -> m a = None) ->
  rw_cells psegs m 0x57ac0 [C1 (Z_to_bv 8 1); C1 (Z_to_bv 8 0); C1 (Z_to_bv 8 0); C1 (Z_to_bv 8 0); C4 (Z_to_bv 64 0)] ->
  rw_cells psegs m 0x57ac8 [C8 auxv; C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 224); C8 (Z_to_bv 64 8); C8 (Z_to_bv 64 0);
                            C8 (Z_to_bv 64 4096); CB 48 (repeat (Z_to_bv 8 0) 48)] ->
  rw_cells psegs m 0x264b0 [C8 (Z_to_bv 64 0x57aa0)] ->
  rw_cells psegs m 0x57aa0 [C8 CAN] ->
  mem_inv psegs m ->
  RHEAP (ps_init (reservedZ psegs) ATOP) [] m
